    Reset(Vec<Transition>),
    Model,
    Driver(Vec<Transition>),
    Done(ConformanceResult),
}

/// A host drives effects and owns I/O, async execution, and cleanup.
pub struct Session {
    id: u32,
    actions: Vec<Value>,
    oracle: Option<Trace>,
    phase: Phase,
    candidates: Vec<Transition>,
    trace: Trace,
}
impl Session {
    pub fn new(model: String, actions: Vec<Value>) -> Result<Self, CoreError> {
        Ok(Self {
            id: 1,
            actions: actions
                .into_iter()
                .map(Value::normalize)
                .collect::<Result<_, _>>()?,
            oracle: None,
            phase: Phase::Initial,
            candidates: vec![],
            trace: Trace {
                format: "modelt.portable-trace".into(),
                version: 1,
                model,
                initial: Value::Null,
                steps: vec![],
            },
        })
    }
    pub fn replay(trace: Trace) -> Result<Self, CoreError> {
        let trace = trace.normalize()?;
        let mut session = Self::new(
            trace.model.clone(),
            trace.steps.iter().map(|step| step.action.clone()).collect(),
        )?;
        session.phase = Phase::Reset(vec![Transition {
            key: String::new(),
            state: Value::Null,
            observation: trace.initial.clone(),
        }]);
        session.oracle = Some(trace);
        Ok(session)
    }
    pub fn effect(&self) -> Effect {
        match &self.phase {
            Phase::Initial => Effect::ModelInitial { id: self.id },
            Phase::Reset(_) => Effect::DriverReset { id: self.id },
            Phase::Model => Effect::ModelStep {
                id: self.id,
                states: self
                    .candidates
                    .iter()
                    .map(|entry| State {
                        key: entry.key.clone(),
                        state: entry.state.clone(),
                    })
                    .collect(),
                action: self.actions[self.trace.steps.len()].clone(),
            },
            Phase::Driver(_) => Effect::DriverStep {
                id: self.id,
                action: self.actions[self.trace.steps.len()].clone(),
            },
            Phase::Done(result) => Effect::Done {
                result: result.clone(),
            },
        }
    }
    pub fn resume(&mut self, id: u32, response: Response) -> Result<Effect, CoreError> {
        if id != self.id || matches!(self.phase, Phase::Done(_)) {
            return Err(CoreError::protocol("Stale or unexpected reply"));
        }
        let response = match (&self.phase, response) {
            (Phase::Initial | Phase::Model, Response::Transitions { transitions }) => {
                Response::Transitions {
                    transitions: transitions
                        .into_iter()
                        .map(|entry| {
                            Ok(Transition {
                                state: entry.state.normalize()?,
                                observation: entry.observation.normalize()?,
                                ..entry
                            })
                        })
                        .collect::<Result<_, CoreError>>()?,
                }
            }
            (Phase::Reset(_) | Phase::Driver(_), Response::Observation { observation }) => {
                Response::Observation {
                    observation: observation.normalize()?,
                }
            }
            _ => {
                return Err(CoreError::protocol(
                    "Reply kind does not match the pending effect",
                ));
            }
        };
        self.id = self
            .id
            .checked_add(1)
            .ok_or_else(|| CoreError::protocol("Request ID exhausted"))?;
        match (self.phase.clone(), response) {
            (Phase::Initial, Response::Transitions { transitions }) => {
                self.phase = Phase::Reset(transitions)
            }
            (Phase::Model, Response::Transitions { transitions }) => {
                if transitions.is_empty() {
                    self.finish(Status::Invalid, vec![]);
                } else {
                    self.phase = Phase::Driver(transitions);
                }
            }
            (Phase::Reset(transitions), Response::Observation { observation }) => {
                self.trace.initial = observation.clone();
                self.accept(transitions, observation);
            }
            (Phase::Driver(transitions), Response::Observation { observation }) => {
                self.trace.steps.push(Step {
                    action: self.actions[self.trace.steps.len()].clone(),
                    observation: observation.clone(),
                });
                self.accept(transitions, observation);
            }
            _ => unreachable!(),
        }
        Ok(self.effect())
    }
    fn accept(&mut self, transitions: Vec<Transition>, actual: Value) {
        self.candidates.clear();
        for entry in transitions
            .iter()
            .filter(|entry| entry.observation == actual)
        {
            if let Some(previous) = self
                .candidates
                .iter_mut()
                .find(|previous| previous.key == entry.key)
            {
                *previous = entry.clone();
            } else {
                self.candidates.push(entry.clone());
            }
        }
        if self.candidates.is_empty() {
            self.finish(
                if transitions.is_empty() {
                    Status::Invalid
                } else {
                    Status::Mismatch
                },
                transitions
                    .iter()
                    .map(|entry| entry.observation.clone())
                    .collect(),
            );
        } else if self.trace.steps.len() == self.actions.len() {
            self.finish(Status::Matched, vec![actual]);
        } else if let Some(oracle) = &self.oracle {
            self.phase = Phase::Driver(vec![Transition {
                key: String::new(),
                state: Value::Null,
                observation: oracle.steps[self.trace.steps.len()].observation.clone(),
            }]);
        } else {
            self.phase = Phase::Model;
        }
    }
    fn finish(&mut self, status: Status, expected: Vec<Value>) {
        let actual = self.trace.steps.last().map_or_else(
            || self.trace.initial.clone(),
            |step| step.observation.clone(),
        );
        self.phase = Phase::Done(ConformanceResult {
            status,
            checked_steps: self.trace.steps.len(),
            actual,
            expected,
            trace: self.trace.clone(),
        });
    }
}

pub struct Engine {
    session: Option<Session>,
    finite: Option<Arc<PreparedFiniteModel>>,
    models: BTreeMap<u32, Arc<PreparedFiniteModel>>,
    safety_programs: BTreeMap<u32, PreparedSafetyProgram>,
    active_handle: Option<u32>,
    next_handle: u32,
    next_id: u32,
}
impl Default for Engine {
    fn default() -> Self {
        Self {
            session: None,
            finite: None,
            models: BTreeMap::new(),
            safety_programs: BTreeMap::new(),
            active_handle: None,
            next_handle: 1,
            next_id: 1,
        }
    }
}
impl Engine {
    pub fn dispatch(&mut self, bytes: &[u8]) -> Message {
        match serde_json::from_slice(bytes) {
            Ok(command) => self.handle(command),
            Err(error) => Message::Error {
                code: "protocol".into(),
                message: error.to_string(),
            },
        }
    }
    pub fn handle(&mut self, command: Command) -> Message {
        match self.execute(command) {
            Ok(message) => message,
            Err(error) => Message::Error {
                code: error.code.into(),
                message: error.message,
            },
        }
    }
    fn execute(&mut self, command: Command) -> Result<Message, CoreError> {
        if command.version != 1 {
            return Err(CoreError::protocol("Unsupported protocol version"));
        }
        match command.request {
            Request::CompileTla {
                source,
                config,
                modules,
                irVersion,
                syntaxVersion,
            } => Ok(Message::Compiled {
                program: compile_tla_bundle(
                    &source,
                    &config,
                    &modules,
                    CompileOptions {
                        irVersion: IrVersion::try_from(irVersion)
                            .map_err(|error| CoreError::protocol(&error.to_string()))?,
                    },
                    syntaxVersion,
                )?,
            }),
            Request::CheckTla {
                source,
                config,
                modules,
                irVersion,
                syntaxVersion,
                bounds,
            } => Ok(Message::Safety {
                result: compile_tla_bundle(
                    &source,
                    &config,
                    &modules,
                    CompileOptions {
                        irVersion: IrVersion::try_from(irVersion)
                            .map_err(|error| CoreError::protocol(&error.to_string()))?,
                    },
                    syntaxVersion,
                )?
                .check(bounds)?,
            }),
            #[cfg(not(target_arch = "wasm32"))]
            Request::CheckSafetyParallel {
                program,
                bounds,
                workers,
            } => Ok(Message::Safety {
                result: program.check_parallel(bounds, workers)?,
            }),
            Request::CheckSafety {
                program,
                bounds,
                options,
            } => Ok(Message::Safety {
                result: program.check_with_options(bounds, options.unwrap_or_default())?,
            }),
            Request::CheckSafetyCoverage { program, bounds } => Ok(Message::SafetyCoverage {
                report: program.check_with_coverage(bounds)?,
            }),
            Request::PrepareSafety { program } => {
                let prepared = program.prepare()?;
                let next = self
                    .next_handle
                    .checked_add(1)
                    .ok_or_else(|| CoreError::protocol("Model handles exhausted"))?;
                let handle = self.next_handle;
                self.safety_programs.insert(handle, prepared);
                self.next_handle = next;
                Ok(Message::SafetyPrepared { handle })
            }
            Request::CheckPreparedSafety {
                handle,
                bounds,
                options,
            } => Ok(Message::Safety {
                result: self
                    .get_safety_program(handle)?
                    .check_with_options(bounds, options.unwrap_or_default())?,
            }),
            Request::CheckPreparedSafetyBatch { handle, jobs } => {
                let program = self.get_safety_program(handle)?;
                if jobs.is_empty() || jobs.len() > 256 {
                    return Err(CoreError::protocol(
                        "Safety batch must contain 1 to 256 jobs",
                    ));
                }
                let results = jobs
                    .into_iter()
                    .map(|job| {
                        match program
                            .check_with_options(job.bounds, job.options.unwrap_or_default())
                        {
                            Ok(result) => SafetyBatchResult::Safety { result },
                            Err(error) => SafetyBatchResult::Error {
                                code: error.code.into(),
                                message: error.message,
                            },
                        }
                    })
                    .collect();
                Ok(Message::SafetyBatch { results })
            }
            Request::ReleaseSafety { handle } => {
                self.safety_programs
                    .remove(&handle)
                    .ok_or_else(|| CoreError::protocol("Unknown safety handle"))?;
                Ok(Message::Released)
            }
            Request::CheckSafetyIncremental {
                enabled,
                program,
                bounds,
                mut cache,
                build_digest,
                max_entries,
            } => {
                let checked = program.check_incremental(
                    bounds,
                    &mut cache,
                    ExpansionOptions {
                        enabled,
                        build_digest: &build_digest,
                        max_entries,
                    },
                )?;
                Ok(Message::IncrementalSafety {
                    result: checked.result,
                    stats: checked.stats,
                    cache,
                })
            }
            Request::MergeSafetyExpansions {
                mut left,
                right,
                max_entries,
            } => {
                left.merge(right, max_entries)?;
                Ok(Message::SafetyExpansions { cache: left })
            }
            Request::LoadModel { model } => {
                let model = Arc::new(model.prepare()?);
                let next = self
                    .next_handle
                    .checked_add(1)
                    .ok_or_else(|| CoreError::protocol("Model handles exhausted"))?;
                let handle = self.next_handle;
                self.models.insert(handle, model);
                self.next_handle = next;
                Ok(Message::Loaded { handle })
            }
            Request::ReleaseModel { handle } => {
                if self.active_handle == Some(handle)
                    && self
                        .session
                        .as_ref()
                        .is_some_and(|session| !matches!(session.phase, Phase::Done(_)))
                {
                    return Err(CoreError::protocol("Model handle is in use"));
                }
                self.models
                    .remove(&handle)
                    .ok_or_else(|| CoreError::protocol("Unknown model handle"))?;
                if self.active_handle == Some(handle) {
                    self.finite = None;
                    self.active_handle = None;
                }
                Ok(Message::Released)
            }
            Request::StartLoaded { handle, actions } => {
                let model = self.get_model(handle)?;
                self.begin(
                    Session::new(model.name().into(), actions)?,
                    Some(model),
                    Some(handle),
                )
            }
            Request::CheckLoaded { handle, traces } => {
                let model = self.get_model(handle)?;
                Ok(Message::Results {
                    results: traces
                        .into_iter()
                        .map(|trace| model.check_history(trace))
                        .collect::<Result<_, _>>()?,
                })
            }
            Request::CheckHistory {
                handle,
                history,
                max_nodes,
            } => Ok(Message::History {
                result: self
                    .get_model(handle)?
                    .check_concurrent(history, max_nodes)?,
            }),
            Request::ReplayHost { tape } => Ok(Message::Host {
                snapshot: replay_host(tape)?,
            }),
            Request::Canonicalize { value } => Ok(Message::Value {
                value: value.normalize()?,
            }),
            Request::Start { model, actions } => {
                self.begin(Session::new(model, actions)?, None, None)
            }
            Request::Replay { trace } => self.begin(Session::replay(trace)?, None, None),
            Request::StartFinite { model, actions } => {
                let model = Arc::new(model.prepare()?);
                self.begin(
                    Session::new(model.name().into(), actions)?,
                    Some(model),
                    None,
                )
            }
            Request::CheckFinite { model, traces } => {
                let model = model.prepare()?;
                Ok(Message::Results {
                    results: traces
                        .into_iter()
                        .map(|trace| model.check_history(trace))
                        .collect::<Result<_, _>>()?,
                })
            }
            Request::ShrinkCandidates { length } => Ok(Message::Candidates {
                ranges: deletion_candidates(length),
            }),
            Request::Resume { id, response } => {
                let session = self
                    .session
                    .as_mut()
                    .ok_or_else(|| CoreError::protocol("No active session"))?;
                let effect = session.resume(id, response)?;
                self.next_id = session.id;
                self.drive(effect)
            }
            Request::Cancel { id } => {
                let session = self
                    .session
                    .as_ref()
                    .ok_or_else(|| CoreError::protocol("No active session"))?;
                if id != session.id || matches!(session.phase, Phase::Done(_)) {
                    return Err(CoreError::protocol("Stale cancellation"));
                }
                self.next_id = id
                    .checked_add(1)
                    .ok_or_else(|| CoreError::protocol("Request ID exhausted"))?;
                self.session = None;
                self.finite = None;
                self.active_handle = None;
                Ok(Message::Cancelled)
            }
        }
    }
    fn begin(
        &mut self,
        mut session: Session,
        finite: Option<Arc<PreparedFiniteModel>>,
        handle: Option<u32>,
    ) -> Result<Message, CoreError> {
        if self
            .session
            .as_ref()
            .is_some_and(|current| !matches!(current.phase, Phase::Done(_)))
        {
            return Err(CoreError::protocol("Session already active"));
        }
        session.id = self.next_id;
        let effect = session.effect();
        self.session = Some(session);
        self.finite = finite;
        self.active_handle = handle;
        self.drive(effect)
    }
    fn get_safety_program(&self, handle: u32) -> Result<&PreparedSafetyProgram, CoreError> {
        self.safety_programs
            .get(&handle)
            .ok_or_else(|| CoreError::protocol("Unknown safety handle"))
    }

    fn get_model(&self, handle: u32) -> Result<Arc<PreparedFiniteModel>, CoreError> {
        self.models
            .get(&handle)
            .cloned()
            .ok_or_else(|| CoreError::protocol("Unknown model handle"))
    }
    fn drive(&mut self, mut effect: Effect) -> Result<Message, CoreError> {
        while let Some(response) = self
            .finite
            .as_ref()
            .map(|model| model.response(&effect))
            .transpose()?
            .flatten()
        {
            let id = match effect {
                Effect::ModelInitial { id } | Effect::ModelStep { id, .. } => id,
                _ => unreachable!(),
            };
            let session = self
                .session
                .as_mut()
                .ok_or_else(|| CoreError::protocol("No finite session"))?;
            effect = session.resume(id, response)?;
            self.next_id = session.id;
        }
        Ok(Message::Effect { effect })
    }
}

use crate::{CoreError, PreparedFiniteModel, Value};
use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, BTreeSet};

#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(tag = "kind", rename_all = "kebab-case", deny_unknown_fields)]
pub enum HistoryEvent {
    Invoke { id: String, action: Value },
    Return { id: String, observation: Value },
    Fail { id: String },
    Unknown { id: String },
    Cancel { id: String },
}
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct ConcurrentHistory {
    pub format: String,
    pub version: u32,
    pub model: String,
    pub initial: Value,
    pub events: Vec<HistoryEvent>,
}
#[derive(Clone, Debug, Deserialize, Serialize, PartialEq)]
#[serde(rename_all = "kebab-case")]
pub enum ConcurrentStatus {
    Linearizable,
    NotLinearizable,
    Inconclusive,
    Empty,
}
#[derive(Clone, Debug, Deserialize, Serialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct ConcurrentResult {
    pub status: ConcurrentStatus,
    pub explored: u32,
    pub order: Vec<String>,
    pub omitted: Vec<String>,
    pub pending: Vec<String>,
}
struct Operation {
    id: String,
    call: usize,
    action: Value,
    returned: Option<usize>,
    observation: Option<Value>,
    ended: bool,
    uncertain: bool,
    failed: bool,
}
struct Frame {
    state: String,
    remaining: Vec<usize>,
    order: Vec<String>,
}

impl PreparedFiniteModel {
    pub fn check_concurrent(
        &self,
        history: ConcurrentHistory,
        max_nodes: u32,
    ) -> Result<ConcurrentResult, CoreError> {
        if max_nodes == 0
            || history.format != "modelt.concurrent-history"
            || history.version != 1
            || history.model.is_empty()
            || history.model != self.name()
        {
            return Err(CoreError::protocol(
                "Invalid concurrent history or node budget",
            ));
        }
        if self.model.initial.is_empty() {
            return Err(CoreError::protocol(
                "Concurrent model has no initial states",
            ));
        }
        let initial = history.initial.normalize()?;
        let mut entries: Vec<Operation> = vec![];
        let mut ids = BTreeMap::new();
        let empty = history.events.is_empty();
        for (index, event) in history.events.into_iter().enumerate() {
            let id = match &event {
                HistoryEvent::Invoke { id, .. }
                | HistoryEvent::Return { id, .. }
                | HistoryEvent::Fail { id }
                | HistoryEvent::Unknown { id }
                | HistoryEvent::Cancel { id } => id,
            };
            if id.is_empty() {
                return Err(CoreError::protocol("Invalid history id"));
            }
            if let HistoryEvent::Invoke { id, action } = event {
                if ids.contains_key(&id) {
                    return Err(CoreError::protocol("Duplicate history id"));
                }
                ids.insert(id.clone(), entries.len());
                entries.push(Operation {
                    id,
                    call: index,
                    action: action.normalize()?,
                    returned: None,
                    observation: None,
                    ended: false,
                    uncertain: false,
                    failed: false,
                });
                continue;
            }
            let entry = entries
                .get_mut(
                    *ids.get(id)
                        .ok_or_else(|| CoreError::protocol("Missing history id"))?,
                )
                .expect("known index");
            let terminal = matches!(
                event,
                HistoryEvent::Return { .. } | HistoryEvent::Fail { .. }
            );
            if entry.ended || (entry.uncertain && !terminal) {
                return Err(CoreError::protocol("Already completed history id"));
            }
            entry.ended = terminal;
            entry.uncertain = !terminal;
            match event {
                HistoryEvent::Return { observation, .. } => {
                    entry.returned = Some(index);
                    entry.observation = Some(observation.normalize()?);
                }
                HistoryEvent::Fail { .. } => entry.failed = true,
                _ => {}
            }
        }
        let entries: Vec<_> = entries.into_iter().filter(|entry| !entry.failed).collect();
        let pending: Vec<_> = entries
            .iter()
            .filter(|entry| entry.returned.is_none())
            .map(|entry| entry.id.clone())
            .collect();
        let result = |status, explored| ConcurrentResult {
            status,
            explored,
            order: vec![],
            omitted: vec![],
            pending: pending.clone(),
        };
        if empty {
            return Ok(result(ConcurrentStatus::Empty, 0));
        }
        let mut stack: Vec<_> = self
            .model
            .initial
            .iter()
            .filter(|entry| entry.observation == initial)
            .rev()
            .map(|entry| Frame {
                state: entry.key.clone(),
                remaining: (0..entries.len()).collect(),
                order: vec![],
            })
            .collect();
        let mut visited = BTreeSet::new();
        let mut explored = 0;
        while let Some(frame) = stack.pop() {
            if frame
                .remaining
                .iter()
                .all(|index| entries[*index].returned.is_none())
            {
                return Ok(ConcurrentResult {
                    status: ConcurrentStatus::Linearizable,
                    explored,
                    order: frame.order,
                    omitted: frame
                        .remaining
                        .iter()
                        .map(|index| entries[*index].id.clone())
                        .collect(),
                    pending,
                });
            }
            if visited.contains(&(frame.state.clone(), frame.remaining.clone())) {
                continue;
            }
            if explored == max_nodes {
                return Ok(result(ConcurrentStatus::Inconclusive, explored));
            }
            visited.insert((frame.state.clone(), frame.remaining.clone()));
            explored += 1;
            let mut children = vec![];
            for index in &frame.remaining {
                let operation = &entries[*index];
                if frame.remaining.iter().any(|other| {
                    entries[*other]
                        .returned
                        .is_some_and(|returned| returned < operation.call)
                }) {
                    continue;
                }
                for edge in self.successors(&frame.state, &operation.action)? {
                    if operation
                        .observation
                        .as_ref()
                        .is_some_and(|expected| *expected != edge.observation)
                    {
                        continue;
                    }
                    let mut order = frame.order.clone();
                    order.push(operation.id.clone());
                    children.push(Frame {
                        state: edge.key.clone(),
                        remaining: frame
                            .remaining
                            .iter()
                            .copied()
                            .filter(|other| other != index)
                            .collect(),
                        order,
                    });
                }
            }
            stack.extend(children.into_iter().rev());
        }
        Ok(result(ConcurrentStatus::NotLinearizable, explored))
    }
}

use crate::{CoreError, Value};
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct HostEvent {
    pub operation: String,
    pub input: Value,
    pub output: Value,
}
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct HostTape {
    pub format: String,
    pub version: u32,
    pub events: Vec<HostEvent>,
}
#[derive(Clone, Debug)]
pub struct HostMessage {
    pub id: u32,
    pub from: String,
    pub to: String,
    pub payload: Value,
}
fn record(fields: Vec<(&str, Value)>) -> Value {
    Value::Record(
        fields
            .into_iter()
            .map(|(name, value)| (name.into(), value))
            .collect(),
    )
    .normalize()
    .expect("valid host record")
}
fn integer(value: u64) -> Value {
    Value::Int(value.to_string())
}
impl HostMessage {
    fn value(&self) -> Value {
        record(vec![
            ("id", integer(u64::from(self.id))),
            ("from", Value::String(self.from.clone())),
            ("to", Value::String(self.to.clone())),
            ("payload", self.payload.clone()),
        ])
    }
}
pub struct SimulationHost {
    random: u32,
    clock: u64,
    running: bool,
    closed: bool,
    failed: bool,
    next_id: u32,
    volatile: BTreeMap<String, Value>,
    durable: BTreeMap<String, Value>,
    messages: Vec<HostMessage>,
    events: Vec<HostEvent>,
    source: Option<Vec<HostEvent>>,
    cursor: usize,
}
impl SimulationHost {
    pub fn new(seed: u32) -> Result<Self, CoreError> {
        if seed == 0 {
            return Err(CoreError::protocol("Invalid simulation seed"));
        }
        Ok(Self {
            random: seed,
            clock: 0,
            running: true,
            closed: false,
            failed: false,
            next_id: 1,
            volatile: BTreeMap::new(),
            durable: BTreeMap::new(),
            messages: vec![],
            events: vec![],
            source: None,
            cursor: 0,
        })
    }
    pub fn replay(tape: HostTape) -> Result<Self, CoreError> {
        if tape.format != "modelt.host-tape" || tape.version != 1 {
            return Err(CoreError::protocol("Unsupported host tape"));
        }
        let mut host = Self::new(1)?;
        host.source = Some(
            tape.events
                .into_iter()
                .map(|event| {
                    Ok(HostEvent {
                        input: event.input.normalize()?,
                        output: event.output.normalize()?,
                        ..event
                    })
                })
                .collect::<Result<_, CoreError>>()?,
        );
        Ok(host)
    }
    fn event(&mut self, operation: &str, input: Value, output: Value) -> Result<(), CoreError> {
        if self.closed || self.failed {
            return Err(CoreError::protocol("Host tape is closed or divergent"));
        }
        let input = input.normalize()?;
        let output = output.normalize()?;
        if self.source.as_ref().is_some_and(|source| {
            !source.get(self.cursor).is_some_and(|event| {
                event.operation == operation && event.input == input && event.output == output
            })
        }) {
            self.failed = true;
            return Err(CoreError::protocol("Host replay differs"));
        }
        self.events.push(HostEvent {
            operation: operation.into(),
            input,
            output,
        });
        self.cursor += 1;
        Ok(())
    }
    fn require_running(&self) -> Result<(), CoreError> {
        if !self.running || self.closed || self.failed {
            Err(CoreError::protocol("Host is stopped"))
        } else {
            Ok(())
        }
    }
    pub fn now(&self) -> u64 {
        self.clock
    }
    pub fn advance(&mut self, amount: u64) -> Result<(), CoreError> {
        let next = self
            .clock
            .checked_add(amount)
            .filter(|next| *next <= 9_007_199_254_740_991)
            .ok_or_else(|| CoreError::protocol("Clock overflow"))?;
        self.event("advance", integer(amount), integer(next))?;
        self.clock = next;
        Ok(())
    }
    pub fn choose(&mut self, label: &str, choices: &[Value]) -> Result<Value, CoreError> {
        let choices = choices
            .iter()
            .cloned()
            .map(Value::normalize)
            .collect::<Result<Vec<_>, _>>()?;
        if choices.is_empty() {
            return Err(CoreError::protocol("No host choices"));
        }
        let selection = if let Some(source) = &self.source {
            source.get(self.cursor).and_then(|event| {
                if let Value::Int(index) = &event.output {
                    index.parse::<usize>().ok()
                } else {
                    None
                }
            })
        } else {
            self.random ^= self.random << 13;
            self.random ^= self.random >> 17;
            self.random ^= self.random << 5;
            Some(self.random as usize % choices.len())
        };
        let Some(index) = selection.filter(|index| *index < choices.len()) else {
            self.failed = true;
            return Err(CoreError::protocol("Invalid replay choice"));
        };
        let chosen = choices[index].clone();
        self.event(
            "choose",
            record(vec![
                ("label", Value::String(label.into())),
                ("choices", Value::List(choices.to_vec())),
            ]),
            integer(index as u64),
        )?;
        Ok(chosen)
    }
    pub fn write(&mut self, key: &str, value: Value) -> Result<(), CoreError> {
        self.require_running()?;
        let value = value.normalize()?;
        self.event(
            "write",
            record(vec![
                ("key", Value::String(key.into())),
                ("value", value.clone()),
            ]),
            Value::Null,
        )?;
        self.volatile.insert(key.into(), value);
        Ok(())
    }
    pub fn read(&self, key: &str) -> Result<Option<Value>, CoreError> {
        self.require_running()?;
        Ok(self.volatile.get(key).cloned())
    }
    pub fn persist(&mut self) -> Result<(), CoreError> {
        self.require_running()?;
        self.event("persist", Value::Null, Value::Null)?;
        self.durable = self.volatile.clone();
        Ok(())
    }
    pub fn crash(&mut self) -> Result<(), CoreError> {
        self.event("crash", Value::Null, Value::Null)?;
        self.running = false;
        self.volatile.clear();
        Ok(())
    }
    pub fn restart(&mut self) -> Result<(), CoreError> {
        self.event("restart", Value::Null, Value::Null)?;
        self.running = true;
        self.volatile = self.durable.clone();
        Ok(())
    }
    pub fn send(&mut self, from: &str, to: &str, payload: Value) -> Result<u32, CoreError> {
        self.require_running()?;
        let payload = payload.normalize()?;
        let id = self.next_id;
        let next = id
            .checked_add(1)
            .ok_or_else(|| CoreError::protocol("Message ID overflow"))?;
        self.event(
            "send",
            record(vec![
                ("from", Value::String(from.into())),
                ("to", Value::String(to.into())),
                ("payload", payload.clone()),
            ]),
            integer(u64::from(id)),
        )?;
        self.messages.push(HostMessage {
            id,
            from: from.into(),
            to: to.into(),
            payload,
        });
        self.next_id = next;
        Ok(id)
    }
    pub fn deliver(&mut self, index: usize) -> Result<HostMessage, CoreError> {
        self.require_running()?;
        let message = self
            .messages
            .get(index)
            .ok_or_else(|| CoreError::protocol("Invalid message index"))?
            .clone();
        self.event(
            "deliver",
            record(vec![
                ("index", integer(index as u64)),
                ("id", integer(u64::from(message.id))),
            ]),
            message.value(),
        )?;
        self.messages.remove(index);
        Ok(message)
    }
    pub fn drop_message(&mut self, index: usize) -> Result<(), CoreError> {
        let message = self
            .messages
            .get(index)
            .ok_or_else(|| CoreError::protocol("Invalid message index"))?;
        self.event(
            "drop",
            record(vec![
                ("index", integer(index as u64)),
                ("id", integer(u64::from(message.id))),
            ]),
            Value::Null,
        )?;
        self.messages.remove(index);
        Ok(())
    }
    pub fn trace(&self) -> HostTape {
        HostTape {
            format: "modelt.host-tape".into(),
            version: 1,
            events: self.events.clone(),
        }
    }
    pub fn finish(&mut self) -> Result<(), CoreError> {
        if self.failed
            || self
                .source
                .as_ref()
                .is_some_and(|source| source.len() != self.cursor)
        {
            return Err(CoreError::protocol("Divergent or unconsumed host tape"));
        }
        self.closed = true;
        Ok(())
    }
    pub fn snapshot(&self) -> Value {
        record(vec![
            ("clock", integer(self.clock)),
            ("running", Value::Bool(self.running)),
            (
                "storage",
                Value::Record(self.volatile.clone().into_iter().collect()),
            ),
            (
                "pending",
                Value::List(self.messages.iter().map(HostMessage::value).collect()),
            ),
        ])
    }
}

fn field<'a>(value: &'a Value, key: &str) -> Result<&'a Value, CoreError> {
    match value {
        Value::Record(entries) => entries
            .iter()
            .find(|(name, _)| name == key)
            .map(|(_, value)| value)
            .ok_or_else(|| CoreError::protocol("Missing host field")),
        _ => Err(CoreError::protocol("Missing host field")),
    }
}
fn text(value: &Value) -> Result<&str, CoreError> {
    if let Value::String(value) = value {
        Ok(value)
    } else {
        Err(CoreError::protocol("Expected host string"))
    }
}
fn unsigned(value: &Value) -> Result<u64, CoreError> {
    if let Value::Int(value) = value {
        value
            .parse()
            .map_err(|_| CoreError::protocol("Expected host integer"))
    } else {
        Err(CoreError::protocol("Expected host integer"))
    }
}
pub fn replay_host(tape: HostTape) -> Result<Value, CoreError> {
    let mut host = SimulationHost::replay(tape.clone())?;
    for event in tape.events {
        match event.operation.as_str() {
            "write" => host.write(
                text(field(&event.input, "key")?)?,
                field(&event.input, "value")?.clone(),
            )?,
            "persist" => host.persist()?,
            "crash" => host.crash()?,
            "restart" => host.restart()?,
            "advance" => host.advance(unsigned(&event.input)?)?,
            "choose" => {
                let Value::List(choices) = field(&event.input, "choices")? else {
                    return Err(CoreError::protocol("Expected host choices"));
                };
                host.choose(text(field(&event.input, "label")?)?, choices)?;
            }
            "send" => {
                host.send(
                    text(field(&event.input, "from")?)?,
                    text(field(&event.input, "to")?)?,
                    field(&event.input, "payload")?.clone(),
                )?;
            }
            "deliver" => {
                host.deliver(
                    usize::try_from(unsigned(field(&event.input, "index")?)?)
                        .map_err(|_| CoreError::protocol("Message index overflow"))?,
                )?;
            }
            "drop" => host.drop_message(
                usize::try_from(unsigned(field(&event.input, "index")?)?)
                    .map_err(|_| CoreError::protocol("Message index overflow"))?,
            )?,
            _ => return Err(CoreError::protocol("Unknown host operation")),
        }
    }
    host.finish()?;
    Ok(host.snapshot())
}
